import React, { useState, useEffect } from "react";

// 1. Receber 'globalSettings'
function ProductForm({ api, onProductSaved, globalSettings }) {

  // Função para criar o estado inicial (limpo)
  const createInitialState = () => ({
    nome: "",
    preco_compra: "",
    preco_venda: "",  // BRL
    peso: "",         // KG
    // Pré-preenche com as configurações globais
    iof_percent: globalSettings.iof_percent || "",
    taxa_dolar: globalSettings.taxa_dolar || "",
  });

  const [form, setForm] = useState(createInitialState());
  // 2. Novo estado para controlar a moeda de compra
  const [moedaCompra, setMoedaCompra] = useState("USD"); // 'USD' ou 'BRL'

  // 3. Efeito para atualizar o formulário se as configurações globais mudarem
  useEffect(() => {
    // Atualiza apenas os campos de IOF e Dólar no formulário
    setForm(f => ({
      ...f,
      iof_percent: globalSettings.iof_percent,
      taxa_dolar: globalSettings.taxa_dolar
    }));
  }, [globalSettings]); // Roda sempre que 'globalSettings' mudar

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      let precoCompraEmUSD = parseFloat(form.preco_compra);
      const taxaDolar = parseFloat(form.taxa_dolar);

      // 4. Lógica de Conversão de Moeda
      if (moedaCompra === "BRL") {
        if (!taxaDolar || taxaDolar === 0) {
          alert("A 'Cotação do Dólar' deve ser maior que zero para converter o preço de BRL para USD.");
          return;
        }
        // Converte o preço de BRL para USD
        precoCompraEmUSD = precoCompraEmUSD / taxaDolar;
      }

      // 5. Prepara os dados para enviar (sempre envia preco_compra em USD)
      const dataToSend = {
        ...form,
        preco_compra: precoCompraEmUSD,
        // Garante que os outros campos são números
        preco_venda: parseFloat(form.preco_venda),
        peso: parseFloat(form.peso),
        iof_percent: parseFloat(form.iof_percent),
        taxa_dolar: taxaDolar,
      };

      await api.post("/produtos", dataToSend);
      alert("Produto cadastrado!");

      // Limpa o formulário, mantendo os padrões globais
      setForm(createInitialState());
      setMoedaCompra("USD"); // Reseta a moeda
      onProductSaved();

    } catch (error) {
      const errorMsg = error.response?.data?.erro || "Erro ao salvar produto.";
      alert(errorMsg);
    }
  };

  return (
    <div>
      <h2>Cadastrar Produto</h2>
      <form onSubmit={handleSubmit}>
        <input name="nome" placeholder="Nome" value={form.nome} onChange={handleChange} required />

        {/* 6. Inputs de Preço de Compra e Seletor de Moeda */}
        <input
          name="preco_compra"
          type="number"
          step="0.01"
          placeholder={`Preço compra (${moedaCompra})`}
          value={form.preco_compra}
          onChange={handleChange}
          required
        />
        <select value={moedaCompra} onChange={(e) => setMoedaCompra(e.target.value)}>
          <option value="USD">USD ($)</option>
          <option value="BRL">BRL (R$)</option>
        </select>

        <input name="preco_venda" type="number" step="0.01" placeholder="Preço venda (BRL)" value={form.preco_venda} onChange={handleChange} required />
        <input name="peso" type="number" step="0.01" placeholder="Peso (kg)" value={form.peso} onChange={handleChange} required />

        {/* 7. Inputs de IOF e Dólar (agora pré-preenchidos) */}
        <input
          name="iof_percent"
          type="number"
          step="0.01"
          placeholder="IOF (%)"
          value={form.iof_percent}
          onChange={handleChange}
          required
        />
        <input
          name="taxa_dolar"
          type="number"
          step="0.01"
          placeholder="Cotação Dólar (R$)"
          value={form.taxa_dolar}
          onChange={handleChange}
          required
        />

        <button type="submit">Salvar</button>
      </form>
    </div>
  );
}

export default ProductForm;
